Address     192.168.10.77   = 11000000.10101000.00001010.01001101
Mask /26    255.255.255.192 = 11111111.11111111.11111111.11000000
AND         network         = 11000000.10101000.00001010.01000000 = .64
OR ~mask    broadcast       = 11000000.10101000.00001010.01111111 = .127
First host .65   Last host .126   Hosts 2^6 - 2 = 62

VLSM plan for 192.168.1.0/24: needs 100, 50, 20 and 2 hosts
 100 hosts -> /25 (126)  192.168.1.0/25     range .0   to .127
  50 hosts -> /26 (62)   192.168.1.128/26   range .128 to .191
  20 hosts -> /27 (30)   192.168.1.192/27   range .192 to .223
   2 hosts -> /30 (2)    192.168.1.224/30   range .224 to .227
 (allocate largest first so every block stays aligned)

#include <stdint.h>
#include <stdio.h>

static uint32_t mask_of(int n) {            /* n in 0..32 */
    return n == 0 ? 0 : 0xFFFFFFFFu << (32 - n);
}

void describe(uint32_t ip, int n) {          /* ip in host order */
    uint32_t m = mask_of(n);
    uint32_t net = ip & m;
    uint32_t bcast = net | ~m;
    uint64_t hosts = (n >= 31) ? (n == 31 ? 2 : 1)
                               : (1ull << (32 - n)) - 2;
    printf("net %u.%u.%u.%u  bcast %u.%u.%u.%u  hosts %llu\n",
        net >> 24, (net >> 16) & 255, (net >> 8) & 255, net & 255,
        bcast >> 24, (bcast >> 16) & 255, (bcast >> 8) & 255, bcast & 255,
        (unsigned long long)hosts);
}

int same_subnet(uint32_t a, uint32_t b, int n) {
    return ((a ^ b) & mask_of(n)) == 0;
}
